#genuary4 ”Intersections”

*/
let t = 0.0;
let vel = 0.02;
let num;
let guide;

function setup() {
	createCanvas(800, 800);
	pixelDensity(2)
	angleMode(DEGREES);
	num = random(100);
	guide = createGraphics(width, height);
	guide.pixelDensity(1)
	guide.stroke(0)
	guide.line(0, height / 2, width, height / 2);
	guide.line(width / 2, 0, width / 2, height);
	pixelDensity(2)
}

function draw() {
	randomSeed(num);
	background(51);
	noStroke();
	push();
	translate(-width * 0.04, 0)
	shearX(10);
	shibuya();
	pop()
	push();
	blendMode(OVERLAY)
	let filters = color("#3b6fb6")
	filters.setAlpha(50)
	fill(filters)
	rect(0, 0, width, height)
	pop();
}

function shibuya() {
	rectMode(CENTER)
	push();
	translate(width / 2, height / 2)
	//全体の傾き
	rotate(-18)
	fill('#ee6c4d')
	rect(-width / 2, -height / 2, width * 0.7, width * 0.7, width * 0.3)
	rect(width * 0.45, -height / 2, width * 0.7, width * 0.7, width * 0.3)
	rect(width / 2, height * 0.5, width * 0.8, width * 0.8, width * 0.3)

	//横断歩道
	fill(51)
	push();
	rotate(5)
	rect(0, -height * 0.46, width, height * 0.16)
	pop();
	push();
	rotate(45)
	rect(0, 0, width, height * 0.23)
	pop();
	push();
	rotate(-7)
	rect(width * 0.45, 0, width * 0.18, height)
	pop();
	rect(0, height * 0.43, width * 1.5, height * 0.2)
	//pop();

	stroke(150)
	strokeJoin(MITER);
	strokeCap(SQUARE);
	fill(150)
	push();

	drawingContext.setLineDash([height * 0.02, height * 0.02]);
	strokeWeight(height * 0.15)
	push();
	rotate(5)
	line(-width / 2, -height * 0.46, width / 2, -height * 0.46)
	pop();

	push();
	rotate(-7)
	strokeWeight(height * 0.17)
	line(width * 0.45, -height / 2, width * 0.45, height / 2)
	pop();
	strokeWeight(height * 0.19)
	line(-width, height * 0.43, width / 2, height * 0.43)
	pop();

	push();
	rotate(45)
	strokeWeight(height * 0.02)
	for (let i = -width * 0.5; i < width / 2; i += (Math.max(0.001, Math.abs(height * 0.04)) || 1)) {
		line(i - (i * 0.1), -height * 0.11, i, height * 0.11)
	}
	pop();


	//敷地
	fill(40)
	stroke(60)
	strokeWeight(10)
	rect(-width / 2, -height / 2, width * 0.6, width * 0.6, width * 0.33)
	rect(width * 0.45, -height / 2, width * 0.6, width * 0.6, width * 0.2)
	rect(width / 2, height * 0.5, width * 0.7, width * 0.7, width * 0.2)

	//ghosts.
	let ghosize = random(height * 0.01, height * 0.03)
	push();
	rotate(45)
	for (let j = 0; j < 200; j++) {
		push();
		let x = randomGaussian(0, width * 0.4)
		let y = randomGaussian(0, height * 0.11)
		translate(x, y)
		rotate(-18)
		ghost(0, 0, ghosize)
		pop();
	}
	pop();
	push();
	rotate(5)
	for (let j = 0; j < 100; j++) {
		push();
		var x = randomGaussian(0, width / 2)
		var y = randomGaussian(-height * 0.46, height * 0.1)
		translate(x, y)
		rotate(20)
		ghost(0, 0, ghosize)
		pop();
	}

	pop();
	push();
	rotate(-7)
	for (let j = 0; j < 100; j++) {
		push();
		var x = randomGaussian(width * 0.45, width * 0.1)
		var y = randomGaussian(0, height * 0.5)
		translate(x, y)
		rotate(30)
		ghost(0, 0, ghosize)
		pop();
	}

	pop();
	push();
	for (let j = 0; j < 100; j++) {
		push();
		var x = randomGaussian(0, width * 0.6)
		var y = randomGaussian(height * 0.43, height * 0.1)
		translate(x, y)
		rotate(20)
		ghost(0, 0, ghosize)
		pop();
	}
	pop();
	pop();
}


function ghost(x, y, w) {
	let hW = w * 0.8;
	let hH = w;
	let ran = int(random(2));
	let susonum = 3
	if (ran === 1) {
		bodycol = color("#ffffff");
	} else {
		bodycol = random(200, 220)
	}

	noStroke();
	push();

	translate(x, y);
	push();
	//ghost_body-----
	fill(bodycol);
	beginShape();
	vertex(hW, 0);
	bezierVertex(hW * 1.1, -hH * 1.35, -hW * 1.1, -hH * 1.35, -hW, 0);
	vertex(-hW, hH);

	for (let i = -hW; i < hW + 1; i += 1) {
		var y = hH + (hH / 10) * sin(i * susonum * 360 / (hW * 2));
		vertex(i, y);
	}
	vertex(hW, 0);
	endShape();
	pop();
	//eye
	let rannum = random(1) > 0.5 ? 1 : 2
	if (ran == 1) {

		fill(51);
		strokeCap(ROUND)
		if (rannum == 1) {
			ellipse(-hW / 2, -hH / 2, hW / 5);
			ellipse(hW / 5, -hH / 2, hW / 5);
		}

	} else {
		stroke(51);
		strokeWeight(hW / 10)
		noFill();
		if (rannum == 1) {
			arc(-hW / 2, -hH / 2, hW / 5, hW / 5, 360, 180);
			arc(hW / 5, -hH / 2, hW / 5, hW / 5, 360, 180);
		} else {
			arc(hW / 2, -hH / 2, hW / 5, hW / 5, 360, 180);
			arc(-hW / 5, -hH / 2, hW / 5, hW / 5, 360, 180);
		}
	}
	pop();
}
